// Webhook v2 puts the POST payload under $json.body. Fall back to $json for manual test runs.
const body = $json.body ?? $json;

const rawEmail = (body.email || '').toString().trim().toLowerCase();
let domain = (body.company_domain || body.domain || body.website || '').toString().trim().toLowerCase();

// Strip protocol, www, paths and query strings so 'https://www.acme.com/pricing' becomes 'acme.com'
domain = domain.replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].split('?')[0].trim();

const freeProviders = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'aol.com', 'icloud.com', 'proton.me', 'protonmail.com', 'gmx.com', 'mail.com', 'yandex.com', 'live.com', 'msn.com'];
const emailDomain = rawEmail.includes('@') ? rawEmail.split('@')[1] : '';

// If no domain was supplied, derive it from a work email (never from a free provider)
if (!domain && emailDomain && !freeProviders.includes(emailDomain)) {
  domain = emailDomain;
}

const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(rawEmail);
const domainOk = domain.length > 3 && domain.includes('.') && !domain.includes(' ');

return [{
  json: {
    email: rawEmail,
    domain,
    name: (body.name || body.full_name || '').toString().trim(),
    source: (body.source || 'webhook').toString().trim(),
    is_free_email: freeProviders.includes(emailDomain),
    valid: emailOk && domainOk,
    received_at: new Date().toISOString(),
  },
}];

// Pull the validated lead forward (the HTTP node output replaced it)
const lead = $('Normalize & Validate Lead').first().json;

// The HTTP node has onError: continue, so a dead site still flows through here
let html = '';
if (typeof $json.data === 'string') html = $json.data;
else if (typeof $json.body === 'string') html = $json.body;

const fetchOk = !$json.error && html.length > 0;

// Grab title + meta description before stripping tags - highest signal-per-token
const titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
const metaMatch = html.match(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']*)["']/i)
  || html.match(/<meta[^>]+content=["']([^"']*)["'][^>]*name=["']description["']/i);

let text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<!--[\s\S]*?-->/g, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;|&apos;/gi, "'")
  .replace(/\s+/g, ' ')
  .trim();

// Decode common HTML entities so titles like 'Stripe &amp; Co' read cleanly
const decode = (s) => s.replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'").replace(/&lt;/gi, '<').replace(/&gt;/gi, '>');

// Cap tokens sent to the AI - 8000 chars of homepage text is plenty for scoring
const MAX_CHARS = 8000;

return [{
  json: {
    ...lead,
    fetch_ok: fetchOk,
    page_title: titleMatch ? decode(titleMatch[1].trim()).slice(0, 200) : '',
    meta_description: metaMatch ? decode(metaMatch[1].trim()).slice(0, 500) : '',
    page_text: text.slice(0, MAX_CHARS),
  },
}];

const lead = $('Extract Homepage Text').first().json;

// Pull the model's text out of the OpenAI-shaped response
let raw = '';
try {
  raw = $json.choices[0].message.content || '';
} catch (e) {
  raw = '';
}

// Strip accidental markdown fences, just in case a provider ignores response_format
raw = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();

let ai = {};
let parseOk = true;
try {
  ai = JSON.parse(raw);
} catch (e) {
  parseOk = false;
}

const clean = (v) => (v === undefined || v === null || v === '') ? 'unknown' : String(v).trim();

let score = parseInt(ai.score, 10);
if (isNaN(score)) {
  score = 1;
  parseOk = false;
}
score = Math.max(1, Math.min(10, score));

return [{
  json: {
    email: lead.email,
    name: lead.name || '',
    domain: lead.domain,
    source: lead.source,
    enriched_at: new Date().toISOString(),
    company_summary: clean(ai.company_summary),
    industry: clean(ai.industry),
    company_size: clean(ai.company_size),
    size_signals: clean(ai.size_signals),
    buying_signals: clean(ai.buying_signals),
    fit_assessment: clean(ai.fit_assessment),
    score,
    score_reasoning: parseOk
      ? clean(ai.score_reasoning)
      : 'AI response could not be parsed - defaulted to score 1. Check the AI node output and your API credential.',
    ai_parse_ok: parseOk,
    homepage_fetched: lead.fetch_ok,
  },
}];
